                ],

                startCarousel() {
                    this.carouselTimer = setInterval(() => {
                        this.activeHero = (this.activeHero + 1) % this.heroSlides.length;
                    }, 5000);
                },
                setHero(index) {
                    this.activeHero = index;
                    clearInterval(this.carouselTimer);
                    this.startCarousel();
                },

                get filteredRecipes() {
                    if (this.activeFilter === 'Favorit 📌') return this.recipes.filter(r => r.bookmarked);
                    if (this.activeFilter === 'Semua') return this.recipes;
                    return this.recipes.filter(r => r.category === this.activeFilter);
                },

                openRecipe(recipe) {
                    this.selectedRecipe = recipe;
                },

                toggleBookmark(recipe) {
                    recipe.bookmarked = !recipe.bookmarked;
                    let msg = recipe.bookmarked ? 'Tersimpan ke Menu Favorit 📌' : 'Dihapus dari Favorit.';
                    this.showToastMsg(msg, 'success');
                },

                loadMore() {
                    if(this.reserveRecipes.length > 0) {
                        this.recipes = [...this.recipes, ...this.reserveRecipes];
                        this.reserveRecipes = [];
                        this.showToastMsg('4 Menu baru berhasil dimuat!', 'success');
                    }
                },

                openAddModal(recipe) {
                    if(recipe.category) this.addForm.category = recipe.category;
                    this.showAddModal = true;
                },

                submitToMealPlan() {
                    this.showAddModal = false;
                    this.selectedRecipe = null;
                    let formattedDate = new Date(this.addForm.date).toLocaleDateString('id-ID', { day: 'numeric', month: 'long' });
                    this.showToastMsg(`Disimpan ke ${this.addForm.category} pada ${formattedDate}!`, 'success');
                },

                showToastMsg(message, type) {
                    this.toast.message = message;
                    this.toast.type = type;
                    this.toast.show = true;
                    setTimeout(() => { this.toast.show = false; }, 3000);
                }
            }));
        });
    </script>
